import Foundation

// Byte-level BPE from OpenAI CLIP's MIT-licensed tokenizer. Vocabulary and
// merge ranks are generated by scripts/prepare_clip.py from that exact release.
struct CLIPTokenizer {
    private struct Pair: Hashable { let first: String; let second: String }
    private let vocabulary: [String: Int]
    private let ranks: [Pair: Int]
    private let bytes: [UInt8: String]
    init(folder: URL) throws {
        vocabulary = try JSONDecoder().decode([String: Int].self, from: Data(contentsOf: folder.appendingPathComponent("vocab.json")))
        let lines = try String(contentsOf: folder.appendingPathComponent("merges.txt"), encoding: .utf8).split(separator: "\n").dropFirst()
        var ranks: [Pair: Int] = [:]
        for (rank, line) in lines.enumerated() {
            let parts = line.split(separator: " ")
            guard parts.count == 2 else { throw SemanticError.resources }
            ranks[Pair(first: String(parts[0]), second: String(parts[1]))] = rank
        }
        self.ranks = ranks
        var visible = Array(33...126) + Array(161...172) + Array(174...255)
        var unicode = visible, extra = 0
        for value in 0...255 where !visible.contains(value) {
            visible.append(value); unicode.append(256 + extra); extra += 1
        }
        bytes = Dictionary(uniqueKeysWithValues: zip(visible, unicode).map { (UInt8($0.0), String(UnicodeScalar($0.1)!)) })
        guard vocabulary.count == 49408, vocabulary["<|startoftext|>"] == 49406,
              vocabulary["<|endoftext|>"] == 49407 else { throw SemanticError.resources }
    }
    func encode(_ text: String) throws -> [Int32] {
        let normalized = text.replacingOccurrences(of: "\\s+", with: " ", options: .regularExpression)
            .trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let regex = try NSRegularExpression(pattern: "<\\|startoftext\\|>|<\\|endoftext\\|>|'s|'t|'re|'ve|'m|'ll|'d|[\\p{L}]+|[\\p{N}]|[^\\s\\p{L}\\p{N}]+")
        var tokens: [Int32] = [49406]
        for match in regex.matches(in: normalized, range: NSRange(normalized.startIndex..., in: normalized)) {
            guard let range = Range(match.range, in: normalized) else { continue }
            let token = normalized[range].utf8.compactMap { bytes[$0] }.joined()
            var word = token.map(String.init)
            guard !word.isEmpty else { continue }
            word[word.count - 1] += "</w>"
            while word.count > 1 {
                let candidates = zip(word, word.dropFirst()).map { Pair(first: $0, second: $1) }
                guard let best = candidates.filter({ ranks[$0] != nil }).min(by: { ranks[$0]! < ranks[$1]! }) else { break }
                var merged: [String] = [], i = 0
                while i < word.count {
                    if i + 1 < word.count, word[i] == best.first, word[i + 1] == best.second {
                        merged.append(word[i] + word[i + 1]); i += 2
                    } else { merged.append(word[i]); i += 1 }
                }
                word = merged
            }
            for part in word {
                guard let id = vocabulary[part] else { throw SemanticError.resources }
                tokens.append(Int32(id))
            }
        }
        tokens = Array(tokens.prefix(76)); tokens.append(49407)
        return tokens + Array(repeating: 0, count: 77 - tokens.count)
    }
}

enum ReviewNavigation {
    static func advanceAfterPreview(id: String?, current: String?, wasPending: Bool, pending: Set<String>) -> Bool {
        guard let id, id == current else { return false }
        return !wasPending && pending.contains(id)
    }
    static func next(from: Int, ids: [String], existing: Set<String>, pending: Set<String>) -> Int {
        var index = min(ids.count, from + 1)
        while index < ids.count && (!existing.contains(ids[index]) || pending.contains(ids[index])) { index += 1 }
        return index
    }
    static func previous(from: Int, ids: [String], existing: Set<String>) -> Int {
        guard !ids.isEmpty else { return 0 }
        var index = min(from - 1, ids.count - 1)
        while index >= 0 {
            if existing.contains(ids[index]) { return index }
            index -= 1
        }
        return min(from, ids.count)
    }
}
